using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ConcentrationEffect", menuName = "Data/Battle/Effects/Sothis/Concentration Effect")]
public class ConcentrationEffect : Effect
{
	[Header("Soul Heat")]
	[SerializeField]
	private SoulHeat soulHeat;

	[SerializeField]
	private BoneKhopeshOmenData boneKhopeshOmenData;

	protected override string GetLocalizedDescription()
	{
		return base.localizationManager.GetLocalizedAtTheStartOfYourTurn(withSpace: true) + base.GetLocalizedDescription();
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (ReferenceSingleton<SothisOmensHandler>.Instance.IsBoneKhopeshOmenActive() && soulHeat.SoulHeatCounter < boneKhopeshOmenData.SoulHeat10Counter)
		{
			int num = soulHeat.SoulHeatCounter + effectAmount;
			if (!ReferenceSingleton<SothisOmensHandler>.Instance.IsFervorousSundialOmenActive())
			{
				num = Mathf.Min(num, 10);
			}
			if (num == boneKhopeshOmenData.SoulHeat10Counter)
			{
				boneKhopeshOmenData.ConcentrationEffectSoulHeat10Triggered();
			}
			else if (soulHeat.SoulHeatCounter < boneKhopeshOmenData.SoulHeat5Counter && num == boneKhopeshOmenData.SoulHeat5Counter)
			{
				boneKhopeshOmenData.ConcentrationEffectSoulHeat5Triggered();
			}
		}
		soulHeat.ModifySoulHeat(effectAmount);
		return effectAmount;
	}
}
